#[cfg(test)]
mod tests {
    use std::{collections::HashSet, fs, path::Path};

    use super::*;

    fn assert_catalog(catalog: &[AttributeModifierTypeCatalogEntry]) {
        let mut names = HashSet::new();
        for (id, entry) in catalog.iter().enumerate() {
            assert_eq!(entry.id, id as i32);
            assert!(names.insert(entry.serialized_name));
        }
    }

    #[test]
    fn attribute_modifier_type_catalogs_preserve_ids_names_and_zero_fallback() {
        assert_catalog(VANILLA_ATTRIBUTE_MODIFIER_OPERATIONS);
        assert_catalog(VANILLA_ATTRIBUTE_MODIFIER_DISPLAY_TYPES);
        assert_eq!(normalize_attribute_modifier_operation_id(3), 0);
        assert_eq!(
            attribute_modifier_operation_name(2),
            Some("add_multiplied_total")
        );
        assert_eq!(
            attribute_modifier_operation_id("add_multiplied_base"),
            Some(1)
        );
        assert_eq!(attribute_modifier_display_name(1), Some("hidden"));
        assert_eq!(attribute_modifier_display_id("override"), Some(2));
        assert_eq!(
            AttributeModifierDisplayType::from_id(1),
            AttributeModifierDisplayType::Hidden
        );
        assert_eq!(
            AttributeModifierDisplayType::from_id(3),
            AttributeModifierDisplayType::Default
        );
    }

    #[test]
    fn production_sources_do_not_redeclare_attribute_modifier_types() {
        fn visit(directory: &Path, violations: &mut Vec<String>) {
            for entry in fs::read_dir(directory).unwrap() {
                let path = entry.unwrap().path();
                if path.is_dir() {
                    visit(&path, violations);
                    continue;
                }
                if path.extension().and_then(|value| value.to_str()) != Some("rs") {
                    continue;
                }
                let display = path.to_string_lossy();
                if display.ends_with("/attribute_modifier_types.rs")
                    || display.ends_with("/tests.rs")
                    || display.contains("/tests/")
                {
                    continue;
                }
                let source = fs::read_to_string(&path).unwrap();
                let production = source.split("#[cfg(test)]").next().unwrap_or(&source);
                if production.contains("fn decode_attribute_modifier_operation_id")
                    || production.contains("fn attribute_modifier_operation_id")
                    || production.contains(
                        "[\"add_value\", \"add_multiplied_base\", \"add_multiplied_total\"]",
                    )
                {
                    violations.push(display.to_string());
                }
            }
        }
        let mut violations = Vec::new();
        visit(
            Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap(),
            &mut violations,
        );
        assert!(
            violations.is_empty(),
            "parallel attribute modifier type owners: {violations:?}"
        );
    }
}
